import numpy as np


def grid(rows, cols):
    return np.arange(rows * cols).reshape(rows, cols)


def last_column(matrix):
    return matrix[:, -1]


def above_mean(values):
    return values[values > values.mean()]


def zero_negatives(values):
    result = values.copy()
    result[result < 0] = 0
    return result

