import numpy as np


def center_columns(m):
    return m - m.mean(axis=0)


def row_shares(m):
    totals = m.sum(axis=1, keepdims=True)
    return np.divide(
        m,
        totals,
        out=np.zeros_like(m, dtype=float),
        where=totals != 0,
    )


def best_column(m):
    return int(m.sum(axis=0).argmax())

