lessons.solution:
import csv
import io


def clean_rows(text):
    rows = []
    seen = set()
    for row in csv.DictReader(io.StringIO(text)):
        name = (row.get("name") or "").strip()
        age = (row.get("age") or "").strip()
        if not name or name.lower() in seen:
            continue
        try:
            age = int(age)
        except ValueError:
            continue
        seen.add(name.lower())
        rows.append({"name": name, "age": age})
    return rows


def average_age(rows):
    if not rows:
        return None
    return sum(r["age"] for r in rows) / len(rows)
